 for(const person of people){const factIds=[];for(const kind of ['motive','means','opportunity']){const id=`${person.id}-${kind}`;factIds.push(id);nodes.push({id,name:`${person.name}: ${kind}`,type:'fact',kind,suspect:person.id,requires:[],alternatives:clues.filter(c=>c.suspect===person.id&&c.kind===kind).map(c=>[c.id])})}nodes.push({id:`conclusion-${person.id}`,name:`${person.name} is responsible`,type:'conclusion',suspect:person.id,requires:[],alternatives:[[...factIds,'death']]})}
